/// Returns the index of the first element equal to zero.
/// If there is no zero, returns v.len().
///
/// Properties:
/// - Result i is in [0, n] where n = v.len()
/// - For all j < i, v[j] != 0
/// - If i < n, then v[i] == 0
pub fn mfirst_cero(v: &[i32]) -> usize {
    v.iter().position(|&x| x == 0).unwrap_or(v.len())
}

